% Phase 4.2 prescribed contact-test inputs, SI units.
t42 = (0:0.0005:2.4)';
q42 = 0.17250000000000001 * ones(size(t42));
v42 = zeros(size(t42)); a42 = v42;
for motion42 = [0 0.7 1.2 1.9; 1 -1 1 -1]
    s42 = min(1,max(0,(t42-motion42(1))/0.4));
    dq42 = 0.0030000000000000001 * motion42(2);
    q42 = q42 + dq42 .* s42.^3 .* (10 - 15*s42 + 6*s42.^2);
    v42 = v42 + dq42/0.4 .* 30 .* s42.^2 .* (1-s42).^2;
    a42 = a42 + dq42/0.4^2 .* 60 .* s42 .* (1-s42) .* (1-2*s42);
end
benchZPosition = timeseries(q42,t42); benchZVelocity = timeseries(v42,t42);
benchZAcceleration = timeseries(a42,t42);
